sample_coassemblies = elusive_clusters.select(
    pl.col("samples").str.split(","),
    "coassembly"
).explode("samples")

coassembly_edges = elusive_edges.with_columns(
    pl.col("sample1").str.replace(r"\.1$", ""),
    pl.col("sample2").str.replace(r"\.1$", ""),
).join(
    sample_coassemblies, left_on="sample1", right_on="samples", how="left"
).join(
    sample_coassemblies, left_on="sample2", right_on="samples", how="left", suffix="2"
).filter(
    pl.col("coassembly") == pl.col("coassembly2")
).with_columns(
    pl.col("target_ids").str.split(",").alias("target")
).explode("target"
).select(["target", "coassembly"]
).unique()

nontarget_otu_table = binned_otu_table.select([
    pl.col("sample").str.replace(r"\.1$", ""),
    "gene", "sequence", "taxonomy", "found_in"
]).join(
    sample_coassemblies, left_on="sample", right_on="samples", how="left"
).drop("sample"
).drop_nulls("coassembly"
).unique(
).with_columns(
    pl.lit(None).cast(str).alias("target")
)

haystack_otu_table = pl.concat([elusive_otu_table, nontarget_otu_table])

sample_pairs = unbinned.join(unbinned, how="cross", suffix="_2"
).filter(
    (pl.col("target") == pl.col("target_2")) &
    (pl.col("sample").str.encode("hex") < pl.col("sample_2").str.encode("hex")) &
    (pl.col("coverage") + pl.col("coverage_2") > MIN_COASSEMBLY_COVERAGE)
).with_columns(
    pl.col("taxonomy").str.split(TAXA_LEVEL_SEP).arr.get(TAXA_LEVEL_OF_INTEREST).alias("taxa_group"),
).filter(
    (pl.col("taxa_group").is_not_null()) &
    ((TAXA_OF_INTEREST == "") |
    (pl.col("taxa_group") == TAXA_OF_INTEREST))
)

sparse_edges = sample_pairs.groupby([
    "taxa_group", "sample", "sample_2"
]).agg([
    pl.count().alias("weight").cast(int),
    pl.col("target").sort().str.concat(",").alias("target_ids")
]).select([
    "taxa_group", "weight", "target_ids",
    pl.col("sample").alias("sample1"),
    pl.col("sample_2").alias("sample2")
])

unbinned = unbinned.drop("found_in"
).with_row_count("target"
).select(
    "gene", "sample", "sequence", "num_hits", "coverage", "taxonomy",
    pl.first("target").over(["gene", "sequence"]).rank("dense") - 1,
).with_columns(
    pl.col("target").cast(pl.Utf8)
)

appraise_binned = appraise_binned.with_columns(
    pl.col("sample").str.replace("\.1$", "")
).filter(
    pl.col("sample") == sample
)

reference_bins = appraise_binned.with_columns(
    pl.col("found_in").str.split(",")
).explode(
    "found_in"
).with_columns(
    pl.col("found_in").str.replace("_protein$", "")
).groupby(
    ["gene", "found_in"]
).agg(
    pl.col("coverage").sum()
).pivot(
    values="coverage", index="gene", columns="found_in",
).melt(
    id_vars="gene", variable_name="found_in", value_name="coverage"
).fill_null(0
).groupby(
    "found_in"
).agg(
    (pl.col("coverage").len() * TRIM_FRACTION).floor().cast(int).alias("cut"),
    pl.col("coverage")
).with_columns(
    pl.col("coverage").arr.sort().arr.slice(
        pl.col("cut"), pl.col("coverage").arr.lengths() - 2 * pl.col("cut")
    ).arr.mean()
).filter(
    pl.col("coverage") > 0
).get_column("found_in"
).to_list()
return set(reference_bins)

appraised = query_read.rename(
